import"./chunk-2NFLSA4Y.js";var r={doppler:{theory:{concept:"[[The Doppler effect is the change in the frequency of a wave registered by an observer when the source of the wave and the observer move relative to each other.]] For sound, the motion is measured relative to the air. When the source and the observer approach each other, the waves reach the observer more often and the pitch is higher; when they move apart, it is lower. For a source moving towards a listener at rest, f\u2032 = f\u2080 \xB7 c / (c \u2212 v\u209B). The effect occurs for all waves: radar speed guns, medical ultrasound and astronomers measuring how fast stars move towards or away from us all use it."},param:{sourceFrequency:"Source frequency",sourceSpeed:"Source speed",observerSpeed:"Listener speed",direction:"Motion",timeStep:"Time step"},hint:{sourceFrequency:"How many sound-wave crests the source emits each second.",sourceSpeed:"The source moves to the right in the scene. Keep it below the speed of sound (343 m/s).",observerSpeed:"The listener moves toward or away from the source, depending on the selected motion.",direction:"Choose whether the source and listener approach or move apart."},preset:{low:"Low",medium:"Medium",high:"High",still:"Still",moving:"Moving",fast:"Fast",slow:"Slow",approach:"Approaching",recede:"Receding"},measure:{sourceFrequency:"Emitted frequency",observedFrequency:"Heard frequency",wavelengthTowardObserver:"Wavelength toward listener",sourceSpeed:"Source speed",observerSpeed:"Listener speed",wavelengthFront:"Wavelength in front",wavelengthBehind:"Wavelength behind",separation:"Source\u2013listener distance",observedPeriod:"Heard period"},variable:{soundSpeed:"Speed of sound in air"},view:{source:"Source",observer:"Listener",approaching:"Emitted: {emitted} \xB7 heard: {heard}",receding:"Emitted: {emitted} \xB7 heard: {heard}",wavefronts:"Sound wavefronts",axis:"Show line of motion"},graph:{frequency:"Heard frequency over time",separation:"Distance between source and listener"},challenge:{samePitch:{title:"No relative motion",description:"Set both speeds to zero. The heard frequency should match the emitted frequency.",hint:"Choose Still for the source and set the listener speed to 0 m/s."},higherPitch:{title:"Hear a higher pitch",description:"Make the source and listener approach so the heard frequency is at least 20% higher.",hint:"Choose Approaching and increase source speed."},lowerPitch:{title:"Hear a lower pitch",description:"Make the source and listener move apart so the heard frequency is lower than the emitted frequency.",hint:"Choose Receding and keep the source speed above zero."},observer:{title:"Listener affects the pitch",description:"Move the listener toward the source and make the heard frequency higher than the source frequency.",hint:"Choose Approaching and set listener speed to at least 20 m/s."},front:{title:"Compressed wavefronts",description:"Show that the wavelength in front of a moving source is shorter than the wavelength behind it.",hint:"Choose Approaching and set source speed above zero."}},section:{what:{title:"What is the Doppler effect?",text:"A siren sounds higher as it approaches and lower after it passes. The source keeps emitting the same frequency; relative motion changes how often wave crests reach the listener."},wavefronts:{title:"Wavefronts bunch up",text:"Each ring shows a crest emitted at an earlier time. As the source moves, crests in front are closer together and crests behind are farther apart."},approach:{title:"When they approach",text:"[[The moving source shortens the wavelength in front of it.]] A listener moving toward the incoming waves meets crests even more often, so the heard frequency rises."},recede:{title:"When they move apart",text:"[[Behind a receding source, wavefronts are spread out.]] A listener moving away from the incoming waves meets them less often, so the heard frequency falls."},observer:{title:"The listener also matters",text:"The Doppler shift depends on both motions relative to the air. A listener moving into incoming crests hears a higher frequency; moving with them lowers it."},uses:{title:"Doppler everywhere",text:"Police and weather radars measure speeds from the Doppler shift of radio waves, and ultrasound scanners use it to see how fast blood flows. Light shows the effect too: galaxies moving away from us look redder (redshift), which revealed that the Universe is expanding. Astronomers also find planets around other stars from the tiny Doppler wobble of the star's light; this method found the first planet around a Sun-like star in 1995, honoured with the 2019 Nobel Prize (Michel Mayor and Didier Queloz)."},try:{title:"Try both directions",text:"Keep the emitted frequency fixed. Compare Approaching and Receding, then change listener speed. The wavefront spacing and heard frequency respond to relative motion."}},formula:{approach:"Source and listener approach",recede:"Source and listener recede",front:"Wavelength in front of the source",behind:"Wavelength behind the source"},assumption:{medium:"Sound travels through still air at a constant 343 m/s; wind and temperature changes are ignored.",subsonic:"Both speeds are below the speed of sound; shock waves and sonic booms are not modeled.",oneDimensional:"The source and listener move along one straight line at constant speeds.",drawing:"The rings are 2D cross-sections of spherical sound waves. Scene positions are compressed (100 m is drawn as 1 unit), and objects are not to scale."}}},o={sim:r};export{o as default,r as sim};
